339	    }
340	
341	    private BigDecimal potOf(Pool pool, int depth) {
342	        Pool parent = parentOf(pool.id());
343	        if (parent == null) {
344	            return pot;
345	        }
346	        if (depth > list.size()) {
347	            return null; // a cycle, which validation never lets in
348	        }
349	        List<BigDecimal> cuts = PoolResponse.cuts(parent, potOf(parent, depth + 1));
350	        if (cuts == null) {
351	            return null;
352	        }
353	        for (int i = 0; i < parent.members().size(); i++) {
354	            Long id = parent.members().get(i).poolId();
355	            if (pool.id().equals(id)) {
356	                return cuts.get(i);
357	            }
358	        }
359	        return null;
360	    }
