367	    private int height(long poolId, int guard) {
368	        Pool pool = find(poolId);
369	        if (pool == null || guard > list.size()) {
370	            return 1;
371	        }
372	        int below = 0;
373	        for (PoolMember m : pool.members()) {
374	            if (m.poolId() != null) {
375	                below = Math.max(below, height(m.poolId(), guard + 1));
376	            }
377	        }
378	        return 1 + below;
379	    }
