import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * A pool's member: a person (personId) or another pool (poolId), its name, its share percent (two decimals), whether
 * it is a person with a retirement date set and its cut of the pool's pot ('': none — the pool is unbalanced, or has
 * no pot, or every member in it is retired, or the member's dates leave out the sheet's today) and its membership's
 * from-date and to-date (null: no start / no end). A pool that is a member of none has the sheet's pot; one that is a member of another, its cut there.
 */
export type PoolMember = {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
  from: string | null;
  to: string | null;
};

/**
 * A pool on the sheet: its members in the order they were added, the total share (a retired member's share counts
 * as given, one whose dates leave out the sheet's today is not counted) and whether that total is exactly 100.00.
 */
export type Pool = { id: number; name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

/** The query key for the sheet's pools; under sheetKey, so re-loading the sheet re-reads them. */
export const poolsKey = (sheet: string) => [...sheetKey(sheet), 'pools'] as const;

/** The sheet's pools, in the order they were added. */
export function usePools() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: poolsKey(sheet),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`),
    enabled: !!sheet,
  });
}

/** Two-decimal cuts added up, skipping blank ones; added in cents so it is exact. */
export function cutTotal(cuts: string[]): string {
  const cents = cuts.filter((c) => c !== '').reduce((sum, c) => sum + Math.round(Number(c) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A person's cuts across every pool they are a member of (a pool showing no cut adds nothing). */
export function personCuts(pools: Pool[], personId: number): string[] {
  return pools.flatMap((p) => p.members.filter((m) => m.personId === personId).map((m) => m.cut));
}
import type { Person } from '../people/people';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { cutTotal, personCuts, usePools } from './pools';

// A person's cut total: their cuts across every pool they are a member of, added up.
export function PersonCutTotal({ person }: { person: Person }) {
  const pools = usePools().data ?? [];
  return <td data-testid="person-cut-total">{cutTotal(personCuts(pools, person.id))}</td>;
}

// The sheet's cut total: everyone's cut total added up.
export function CutTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const pools = usePools().data ?? [];

  if (!user || !sheet) return null;

  return (
    <p>
      Cut total: <strong data-testid="rollup-cut-total">{cutTotal(people.map((p) => cutTotal(personCuts(pools, p.id))))}</strong>
    </p>
  );
}
import { useQueryClient } from '@tanstack/react-query';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { csvField } from './ExportPeople';
import { freshPools } from './fresh';

// The button that downloads the pools as a CSV file: one line per member, pools in the order added and
// members in the order added, a pool member as pool:<name> and the cut as the pool's row shows it (empty
// when none). The pools are re-read from the store first, so the cuts are current (as of the screen's
// as-of date, when one is set). Quoted and ended as the people export.
export function ExportPools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();

  if (!user || !sheet) return null;

  const download = async () => {
    const pools = await freshPools(queryClient, sheet);
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of pools) {
      for (const m of p.members) {
        lines.push([p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]);
      }
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `pools-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-pools" onClick={download}>
      Export pools (CSV)
    </button>
  );
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { poolsKey, usePools } from './pools';
import type { Pool } from './pools';
import { useOneAtATime } from '../../query/useOneAtATime';

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's pools and the form that adds one; a blank name, or one already a pool's, is refused.
export function Pools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const pools = usePools().data ?? [];
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { name: string }) =>
      postJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setName('');
      setError('');
      queryClient.setQueryData(poolsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
    },
    onError: () => setError('That pool was refused: it needs a name no other pool has.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const trimmed = name.trim();
    if (!trimmed) {
      setError('Type the pool name.');
      return;
    }
    if (pools.some((p) => p.name === trimmed)) {
      setError(`There is already a pool named ${trimmed}.`);
      return;
    }
    once(() => add.mutateAsync({ name }));
  };

  return (
    <section data-testid="pools">
      <ul data-testid="pool-list">
        {pools.map((p) => (
          <PoolRow key={p.id} pool={p} pools={pools} />
        ))}
      </ul>
      <form onSubmit={submit} data-testid="pool-form">
        <input
          data-testid="pool-form-name"
          placeholder="Pool name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {error && <span data-testid="pool-form-error">{error}</span>}
      </form>
    </section>
  );
}

const EMPTY = { member: '', share: '', from: '', to: '' };

// A pool's row: its members with their shares and cuts of the pot (blank: an unbalanced pool, or no pot), its total share and whether it is balanced, and the form that adds a
// member — a person, or another pool chosen as pool:<name>; a person already in the pool, a pool already a member of
// one, one that would contain itself or make a chain of pools more than three deep, or a share not more than 0.00 and
// at most 100.00 (two decimals), or a to-date before the from-date (both optional, yyyy-mm-dd), is refused. A member
// whose dates leave out the sheet's today is not in the total share and has no cut.
function PoolRow({ pool, pools }: { pool: Pool; pools: Pool[] }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const [form, setForm] = useState(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { personId?: number; poolId?: number; share: string; from: string | null; to: string | null }) =>
      postJson<Pool[]>(
        `/api/sheets/${encodeURIComponent(sheet)}/pools/${pool.id}/members?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (saved) => {
      setForm(EMPTY);
      setError('');
      queryClient.setQueryData(poolsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
    },
    onError: () =>
      setError(
        'That member was refused: a person not yet in the pool, or a pool in no other that does not contain this one and keeps chains at most three deep, with a share over 0.00 and at most 100.00.',
      ),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.member) {
      setError('Choose a person or a pool.');
      return;
    }
    const [kind, idText] = form.member.split(':');
    const id = Number(idText);
    if (kind === 'person' && pool.members.some((m) => m.personId === id)) {
      setError('That person is already in the pool.');
      return;
    }
    if (kind === 'pool' && pools.some((p) => p.members.some((m) => m.poolId === id))) {
      setError('That pool is already a member of a pool.');
      return;
    }
    const share = form.share.trim();
    if (!SHARE.test(share) || Number(share) <= 0 || Number(share) > 100) {
      setError('Type a share more than 0.00 and at most 100.00, with at most two decimals.');
      return;
    }
    const from = form.from.trim();
    const to = form.to.trim();
    if ((from && !DATE.test(from)) || (to && !DATE.test(to))) {
      setError('Type the dates as yyyy-mm-dd.');
      return;
    }
    if (from && to && to < from) {
      setError('The to-date is before the from-date.');
      return;
    }
    const dates = { from: from || null, to: to || null };
    once(() => add.mutateAsync(kind === 'pool' ? { poolId: id, share, ...dates } : { personId: id, share, ...dates }));
  };

  const change = (patch: Partial<typeof EMPTY>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <span data-testid="pool-name">{pool.name}</span> total <span data-testid="pool-total-share">{pool.totalShare}</span>{' '}
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.poolId !== null ? `pool-${m.poolId}` : m.personId}
            data-testid={`pool-member-${pool.name}-${m.poolId !== null ? `pool-${m.name}` : m.personId}`}
          >
            <span data-testid="pool-member-name">{m.name}</span> <span data-testid="pool-share">{m.share}</span>
            {m.retired && ' (retired)'}
            {(m.from || m.to) && ` (${m.from ?? 'start'} to ${m.to ?? 'no end'})`} cut <span data-testid="pool-cut">{m.cut}</span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select data-testid="pool-member-select" value={form.member} onChange={(e) => change({ member: e.target.value })}>
          <option value="">Choose a person or a pool</option>
          {people.map((p) => (
            <option key={p.id} value={`person:${p.id}`}>
              {p.name}
            </option>
          ))}
          {pools.map((p) => (
            <option key={`pool-${p.id}`} value={`pool:${p.id}`}>
              pool:{p.name}
            </option>
          ))}
        </select>
        <input data-testid="pool-member-share" placeholder="Share %" value={form.share} onChange={(e) => change({ share: e.target.value })} />
        <input data-testid="pool-member-from" placeholder="From yyyy-mm-dd (blank: no start)" value={form.from} onChange={(e) => change({ from: e.target.value })} />
        <input data-testid="pool-member-to" placeholder="To yyyy-mm-dd (blank: no end)" value={form.to} onChange={(e) => change({ to: e.target.value })} />
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {error && <span data-testid="pool-error">{error}</span>}
      </form>
    </li>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useClaims } from '../claims/claims';
import { liveHolds, usePeople } from '../people/people';
import { useDueRules } from '../settings/settings';
import { NA, personDue, total, useRates } from '../rates/rates';

/** A crew's lead or member: a person of the sheet. */
export type CrewPerson = { id: number; name: string };

/** A crew on the sheet: its name, its lead and its members in the order they were added. */
export type Crew = { id: number; name: string; lead: CrewPerson; members: CrewPerson[] };

/** The query key for the sheet's crews; under sheetKey, so re-loading the sheet re-reads them. */
export const crewsKey = (sheet: string) => [...sheetKey(sheet), 'crews'] as const;

/** The sheet's crews, in the order they were added. */
export function useCrews() {
  const [sheet] = useCurrentSheet();
